        return 0 as c_int;
    }

    // SAFETY: `in_0` is non-null after the guard above; the caller provides
    // `*inlen` readable input bytes for this extern-C API; this shared slice
    // does not alias any mutable reference created here.
    let input = unsafe { core::slice::from_raw_parts(in_0, *inlen as usize) };
    // SAFETY: `out` is non-null after the guard above; the caller provides
    // `*outlen` writable output bytes for this extern-C API; this mutable slice
    // is the only `&mut` view created for that region in this function.
    let output = unsafe { core::slice::from_raw_parts_mut(out, *outlen as usize) };

    let input_len = input.len();
    let output_len = output.len();

    let mut processed_idx: usize = 0;
    let mut in_idx: usize = 0;
    let mut out_idx: usize = 0;

    while in_idx < input_len {
        let d0 = input[in_idx] as c_uint;
        in_idx += 1;

        let mut c: c_uint;
        let mut trailing: c_int;

        if d0 < 0x80 as c_uint {
            c = d0;
            trailing = 0 as c_int;
        } else if d0 < 0xc0 as c_uint {
            // SAFETY: `outlen` and `inlen` were checked non-null above.
            unsafe {
                *outlen = out_idx as c_int;
                *inlen = processed_idx as c_int;
            }
            return -(2 as c_int);
        } else if d0 < 0xe0 as c_uint {
            c = d0 & 0x1f as c_uint;
            trailing = 1 as c_int;
        } else if d0 < 0xf0 as c_uint {
            c = d0 & 0xf as c_uint;
            trailing = 2 as c_int;
        } else if d0 < 0xf8 as c_uint {
            c = d0 & 0x7 as c_uint;
            trailing = 3 as c_int;
        } else {
            // SAFETY: `outlen` and `inlen` were checked non-null above.
            unsafe {
                *outlen = out_idx as c_int;
                *inlen = processed_idx as c_int;
            }
            return -(2 as c_int);
        }

        if input_len.wrapping_sub(in_idx) < trailing as usize {
            break;
        }

        while trailing != 0 {
            if in_idx >= input_len {
                break;
