                break;
            }
            c <<= 6 as c_int;
            c |= d & 0x3f as c_uint;
            trailing -= 1;
        }

        if c < 0x80 as c_uint {
            if out_idx + 1 >= output_len {
                break;
            }
            output[out_idx] = c as c_uchar;
            out_idx += 1;
        } else {
            let mut len: c_int;
            let ent = htmlEntityValueLookup(c);
            let cp: *const c_char;
            let mut nbuf: [c_char; 16] = [0; 16];

            if ent.is_null() {
                snprintf(
                    nbuf.as_mut_ptr(),
                    ::core::mem::size_of::<[c_char; 16]>() as size_t,
                    b"#%u\0" as *const u8 as *const c_char,
                    c,
                );
