                core::ptr::copy_nonoverlapping(
                    cp as *const c_uchar,
                    output.as_mut_ptr().add(out_idx),
                    len as usize,
                );
            }
            out_idx += len as usize;

            output[out_idx] = ';' as i32 as c_uchar;
            out_idx += 1;
        }

        processed_idx = in_idx;
    }

    // SAFETY: `outlen` and `inlen` were checked non-null above.
    unsafe {
        *outlen = out_idx as c_int;
        *inlen = processed_idx as c_int;
    }
    return 0 as c_int;
}

